/* C1 guest probe: every generated byte is independently checked by collect. */
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static unsigned char block[7777];
static unsigned char pattern(unsigned long position) {
    return (unsigned char)((position * 73u + (position >> 8) * 19u + 11u) & 255u);
}
static void relinquish(void) {
#ifdef XOS_REFERENCE
    /* Reference execution never reads a nonblocking UART. */
#else
    __asm__ volatile("int $0x80" : : "a"(3ul), "D"(0ul), "S"(0ul), "d"(0ul) : "memory");
#endif
}
static int write_all(int fd, const void *raw, unsigned long count) {
    const unsigned char *data = raw;
    while (count) {
        ssize_t n = write(fd, data, count);
        if (n <= 0) return -1;
        data += n; count -= (unsigned long)n;
    }
    return 0;
}
static int generate(unsigned long count) {
    unsigned long offset = 0, short_writes = 0;
    while (offset < count) {
        unsigned long amount = count - offset;
        if (amount > sizeof(block)) amount = sizeof(block);
        for (unsigned long i = 0; i < amount; ++i) block[i] = pattern(offset + i);
        ssize_t n = write(1, block, amount);
        if (n < 0) {
            fprintf(stderr, "C1_WRITE_ERROR errno=%d EPIPE=%d bytes=%lu\n", errno, EPIPE, offset);
            return errno == EPIPE ? 31 : 32;
        }
        if (!n) return 33;
        if ((unsigned long)n < amount) ++short_writes;
        offset += (unsigned long)n;
    }
    fprintf(stderr, "C1_GENERATED bytes=%lu short_writes=%lu\n", offset, short_writes);
    return 0;
}
static int consume(const char *path, unsigned long expected, int verify) {
    unsigned long offset = 0, reads = 0;
    int output = path ? open(path, O_WRONLY | O_CREAT | O_TRUNC, 0666) : -1;
    if (path && output < 0) return 40;
    for (;;) {
        ssize_t n = read(0, block, 257);
        if (n < 0) return 41;
        if (!n) break;
        ++reads;
        if (verify) {
            for (ssize_t i = 0; i < n; ++i)
                if (block[i] != pattern(offset + (unsigned long)i)) return 42;
        }
        if (output >= 0 && write_all(output, block, (unsigned long)n)) return 43;
        offset += (unsigned long)n;
    }
    if (output >= 0 && close(output)) return 44;
    if (verify && offset != expected) {
        fprintf(stderr, "C1_LENGTH expected=%lu actual=%lu\n", expected, offset);
        return 45;
    }
    printf("C1_CHECK bytes=%lu reads=%lu eof=1\n", offset, reads);
    return 0;
}
#ifndef XOS_REFERENCE
static long call(unsigned long number, unsigned long a, unsigned long b, unsigned long c) {
    long result;
    __asm__ volatile("int $0x80" : "=a"(result) : "a"(number), "D"(a), "S"(b), "d"(c) : "memory");
    return result;
}
static int raw_checks(void) {
    struct { unsigned int reader, writer; } pair;
    unsigned int stale = 0;
    for (int round = 0; round < 20; ++round) {
        if (call(30, (unsigned long)&pair, 0, 0)) return 60;
        if (stale && call(54, stale, 0, 0) != -1) return 61;
        if (call(54, pair.reader, 1, 0) != -2 || call(54, pair.writer, 0, 1) != -2) return 62;
        if (call(54, 12345, 0, 0) != -1 || call(54, 0, 0, 0) != -3) return 63;
        if (call(54, pair.writer, 0, 0)) return 64;
        if (call(31, pair.reader, (unsigned long)block, 1) != -3) return 65;
        if (call(32, pair.reader, (unsigned long)block, 1) != -1 ||
            call(31, pair.writer, (unsigned long)block, 1) != -1) return 66;
        if (call(32, pair.writer, (unsigned long)block, 7777) != 4096) return 67;
        if (call(32, pair.writer, (unsigned long)block, 1) != -3) return 68;
        if (call(54, pair.reader, 0, 0)) return 69;
        if (call(31, pair.reader, (unsigned long)block, 7777) != 4096) return 70;
        if (call(33, pair.writer, 0, 0) || call(54, pair.reader, 0, 0) ||
            call(31, pair.reader, (unsigned long)block, 1)) return 71;
        if (call(33, pair.reader, 0, 0)) return 72;
        stale = pair.reader;
        if (call(30, (unsigned long)&pair, 0, 0) || call(33, pair.reader, 0, 0) ||
            call(54, pair.writer, 0, 0) || call(32, pair.writer, (unsigned long)block, 1) != -7 ||
            call(33, pair.writer, 0, 0)) return 73;
    }
    printf("C1_RAW rounds=20 permissions=ok arguments=ok short_io=ok eof=ok epipe=ok stale=ok\n");
    return 0;
}
#endif
int main(int argc, char **argv) {
    if (argc < 2) return 2;
    const char *mode = argv[1];
    unsigned long count = argc > 2 ? strtoul(argv[2], 0, 10) : 0;
    if (!strcmp(mode, "generate")) return generate(count);
    if (!strcmp(mode, "copy")) {
        for (;;) {
            ssize_t n = read(0, block, 2347);
            if (n < 0) return 11;
            if (!n) return 0;
            if (write_all(1, block, (unsigned long)n)) return errno == EPIPE ? 31 : 12;
        }
    }
    if (!strcmp(mode, "collect")) return argc == 4 ? consume(argv[3], count, 1) : 3;
    if (!strcmp(mode, "expect")) return consume(0, count, 1);
    if (!strcmp(mode, "early")) {
        unsigned long done = 0;
        while (done < count) {
            unsigned long amount = count - done;
            if (amount > sizeof(block)) amount = sizeof(block);
            ssize_t n = read(0, block, amount);
            if (n <= 0) return 13;
            done += (unsigned long)n;
        }
        close(0);
        fprintf(stderr, "C1_EARLY bytes=%lu\n", done);
        return 0;
    }
    if (!strcmp(mode, "spin")) {
        fprintf(stderr, "C1_SPIN_READY\n");
        for (;;) __asm__ volatile("" : : : "memory");
    }
    if (!strcmp(mode, "fault")) { *(volatile unsigned char *)0x1000 = 1; return 99; }
    if (!strcmp(mode, "exit")) return (int)count;
    if (!strcmp(mode, "input")) {
        fprintf(stderr, "C1_INPUT_READY\n");
        for (;;) {
            unsigned char value;
            ssize_t n = read(0, &value, 1);
            if (n < 0 && errno == EAGAIN) { relinquish(); continue; }
            if (n != 1) return 14;
            if (value == '\r' || value == '\n') return write_all(1, "\n", 1) ? 15 : 0;
            if (write_all(1, &value, 1)) return 16;
        }
    }
#ifndef XOS_REFERENCE
    if (!strcmp(mode, "raw")) return raw_checks();
#endif
    return 4;
}
